"""Pinned old contracts and behavior expectations are never regenerated by tests."""
from copy import deepcopy
import json
from pathlib import Path
import subprocess
import tempfile
from types import SimpleNamespace
import unittest
from unittest.mock import patch

from compatibility import compare_states
from config import consumers, load_config
from adoption import load_policy
from consumer import content_errors, envelope_errors, load_consumer, run_vector
from release import ReleaseError, canonical

BASELINE = Path(__file__).with_name("fixtures") / "consumer-0.1.0.json"
BASELINE_SHA = "f7df720d08a8334a1d976cc7f1c28c7a9f4a3dec1612da204dd59b420ac886e1"


class ConsumerTests(unittest.TestCase):
    @classmethod
    def setUpClass(cls):
        cls.frozen = load_consumer(BASELINE, BASELINE_SHA)

    def test_config_pins_real_first_release_without_record_mode(self):
        self.assertEqual(len(self.frozen["interface"]["operations"]), 13)
        self.assertEqual(len(self.frozen["vectors"]), 23)
        self.assertEqual(self.frozen["sourceReleaseId"], "55b2c482617005e95c353523b8e8926b8db538e5872bb06362cde28edd00f9ff")
        self.assertEqual(load_policy(load_config())["historical"][0], self.frozen)
        self.assertEqual(consumers(load_config())[0]["manifest"]["defaultPageSchema"], "6.89")
        self.assertEqual(BASELINE.with_suffix('.sha256').read_text(encoding='utf-8').strip(), BASELINE_SHA)
        source = Path(__file__).with_name("package_cli.py").read_text(encoding="utf-8")
        self.assertNotIn('"record"', source)
        self.assertNotIn('"freeze"', source)

    def test_tampering_with_frozen_snapshot_is_rejected(self):
        with tempfile.TemporaryDirectory() as temporary:
            changed = Path(temporary) / "consumer.json"
            changed.write_bytes(BASELINE.read_bytes() + b" ")
            with self.assertRaises(ReleaseError) as error:
                load_consumer(changed, BASELINE_SHA)
            self.assertEqual(error.exception.code, "CONSUMER_SNAPSHOT_CHANGED")

    def states(self):
        before = {key: deepcopy(self.frozen[key]) for key in ("manifest", "interface", "resources")}
        after = deepcopy(before)
        after["manifest"]["releaseVersion"] = "0.2.0"
        after["manifest"]["interfaceVersion"] = "1.1.0"
        after["interface"]["version"] = "1.1.0"
        return before, after

    def test_compatible_additions_preserve_every_old_operation_and_resource(self):
        before, after = self.states()
        after["interface"]["operations"]["new.operation"] = deepcopy(after["interface"]["operations"]["page.validate"])
        after["resources"]["new:resource"] = "new.json"
        report = compare_states(before, after)
        self.assertEqual(report["status"], "ok")
        self.assertTrue(report["eligibleForSmoke"])
        self.assertFalse(report["automaticPromotion"] if "automaticPromotion" in report else False)

    def test_even_optional_old_input_and_error_changes_need_migration(self):
        before, after = self.states()
        after["interface"]["operations"]["page.validate"]["inputSchema"]["properties"]["optional"] = {"type": "string"}
        self.assertEqual(compare_states(before, after)["status"], "needs_migration")

    def test_json_boolean_and_number_are_not_equal_contracts_or_outputs(self):
        before, after = self.states()
        before["interface"]["operations"]["page.validate"]["inputSchema"]["properties"]["test"] = {"enum": [1]}
        after["interface"]["operations"]["page.validate"]["inputSchema"]["properties"]["test"] = {"enum": [True]}
        self.assertEqual(compare_states(before, after)["status"], "needs_migration")
        expected = {"data": {"value": 1}, "diagnostics": []}
        self.assertIn("product data changed", content_errors({"data": {"value": True}, "diagnostics": []}, expected))
        before, after = self.states()
        after["interface"]["operations"]["page.validate"]["errorCodes"].append("NEW_ERROR")
        self.assertEqual(compare_states(before, after)["status"], "needs_migration")

    def test_removed_id_runtime_default_and_operation_are_rejected(self):
        for field in ("resource", "runtime", "default", "operation"):
            before, after = self.states()
            if field == "resource":
                after["resources"].pop(next(iter(after["resources"])))
            elif field == "runtime":
                after["manifest"]["runtime"]["node"] = ">=24"
            elif field == "default":
                after["manifest"]["defaultPageSchema"] = "6.83"
            else:
                after["interface"]["operations"].pop("page.validate")
            self.assertEqual(compare_states(before, after)["status"], "needs_migration", field)

    def test_frozen_content_projection_allows_additive_index_entries(self):
        vector = self.frozen["vectors"][0]
        result = {"data": {**vector["expected"]["dataProjection"], "content": {"new": "resource"}, "contentSha256": "new-version"},
                  "diagnostics": vector["expected"]["diagnostics"]}
        self.assertEqual(content_errors(result, vector["expected"]), [])
        result["data"]["key"] = "different-key"
        self.assertTrue(content_errors(result, vector["expected"]))

    def test_ordered_diagnostics_and_complete_product_data_are_fixed(self):
        vector = next(value for value in self.frozen["vectors"] if len(value["expected"]["diagnostics"]) > 1)
        result = deepcopy(vector["expected"])
        self.assertEqual(content_errors(result, vector["expected"]), [])
        result["diagnostics"].reverse()
        self.assertEqual(content_errors(result, vector["expected"]), ["ordered diagnostics changed"])
        result = deepcopy(vector["expected"])
        result["data"]["extra"] = "changed"
        self.assertIn("product data changed", content_errors(result, vector["expected"]))

    def test_replay_reports_malformed_stdout_without_recording_new_expectations(self):
        vector = self.frozen["vectors"][1]
        original = BASELINE.read_bytes()
        child = SimpleNamespace(returncode=0, stdout=b"[]", stderr=b"")
        with patch("consumer.subprocess.run", return_value=child):
            report = run_vector(Path("/not-a-product"), vector)
        self.assertFalse(report["passed"])
        self.assertIn("result envelope changed", report["details"])
        self.assertEqual(BASELINE.read_bytes(), original)

    def test_replay_checks_exit_and_envelope_identity(self):
        vector = self.frozen["vectors"][1]
        result = {"format": "metriccanvas-mc-result/1", "requestId": vector["request"]["requestId"],
                  "operation": vector["operation"], "status": vector["expected"]["status"],
                  "data": vector["expected"]["data"], "diagnostics": vector["expected"]["diagnostics"]}
        self.assertEqual(envelope_errors(result, vector), [])
        with patch("consumer.subprocess.run", return_value=SimpleNamespace(returncode=3, stdout=canonical(result), stderr=b"")):
            report = run_vector(Path("/not-a-product"), vector)
        self.assertEqual(report["details"], ["exit code changed"])


if __name__ == "__main__":
    unittest.main()
